static constexpr size_t kPixelCount = 400u * 240u;

static bool render(uint32_t *output, size_t capacity)
{
    if (!output || capacity < kPixelCount) return false;
    size_t src = 0, dst = 0;
    while (src < sizeof kPacked && dst < kPixelCount) {
        const uint8_t token = kPacked[src++];
        if (token < 128) {
            const size_t length = size_t(token) + 1;
            if (src + length > sizeof kPacked || dst + length > kPixelCount)
                return false;
            for (size_t j = 0; j < length; ++j) {
                const uint8_t index = kPacked[src++];
                if (index >= 32) return false;
                output[dst++] = kPalette[index];
            }
        } else {
            const size_t length = size_t(token & 127) + 3;
            if (src + 2 > sizeof kPacked || dst + length > kPixelCount)
                return false;
            const size_t distance = size_t(kPacked[src]) | (size_t(kPacked[src+1]) << 8);
            src += 2;
            if (!distance || distance > dst) return false;
            for (size_t j = 0; j < length; ++j) {
                output[dst] = output[dst - distance];
                ++dst;
            }
        }
    }
    return src == sizeof kPacked && dst == kPixelCount;
}
